interface.definition:
if(or(
    a!isNullOrEmpty(ri!contents),
    ri!showWhen = false
  ), {},
  a!localVariables(
    /*local!isStandardAlignment: a!defaultValue(value: ri!isStandardAlignment, default: true),*/
    local!numContents: count(ri!contents),
    /*Some math, defaults and null handling*/
    local!numColumnsEmpty:
    or(
      isnull(ri!numColumns),
      ri!numColumns = 0
    ),
    local!numColumns:
    if(local!numColumnsEmpty, 
      local!numContents,
      ri!numColumns
    ),
    local!numRows: 
    if(local!numColumnsEmpty,  
      1,
      ceiling(local!numContents / ri!numColumns, 1)
    ),
    /*Generate placeholders*/
    local!enumeratedColumns: enumerate(local!numColumns),
    local!enumeratedRows: enumerate(local!numRows),

    local!applyPlaceholders: a!defaultValue(value: ri!applyPlaceholders, default: true),
    local!enumeratedWidths:
    if(a!isNullOrEmpty(ri!width),
      null,
      if(count(ri!width) = 1,
        rdrop(split(rept(ri!width[1] & ";", local!numColumns * (local!enumeratedRows + 1)), ";"), 1),
        ri!width
      )
    ),
    /*if(local!isStandardAlignment,*/
      /*Account for rows*/
      /*a!columnsLayout(*/
        /*showDividers: ri!showDividers,*/
        /*alignVertical: ri!alignVertical,*/
        /*spacing: ri!spacing,*/
        /*marginBelow: ri!marginBelow,*/
        /*stackWhen: a!defaultValue(value: ri!stackWhen, default: cons!IEM_ICO_DEFAULT_STACK_WHEN),*/
        /*columns: */
        /*Account for columns, and add empty columns if applicable*/
        /*a!forEach(*/
          /*items: local!enumeratedColumns,*/
          /*expression: */
          /*a!localVariables(*/
            /*local!indexColumn: (local!indexRow * local!numColumns) + fv!index,*/
            /*if(and(*/
              /*ri!applyPlaceholders = false,*/
              /*local!indexColumn > local!numContents*/
            /*),*/
            /*{},*/
            /*if(local!indexColumn > local!numContents,*/
            /*if(local!applyPlaceholders,*/
            /*a!columnLayout(*/
              /*width: index(local!enumeratedWidths, fv!index, null)*/
            /*),*/
            /*null*/
            /*),*/
            /*a!columnLayout(*/
              /*contents: index({ri!contents}, local!indexColumn, {}),*/
              /*width: index(local!enumeratedWidths, fv!index, null)*/
            /*)*/
            /*)*/
            /*)*/
          /*)*/
        /*)*/
      /*),*/
      /*Account for rows*/
      #"SYSTEM_SYSRULES_forEach"(
        items: local!enumeratedRows,
        expression: 
        #"SYSTEM_SYSRULES_columnsLayout"(
          showDividers: ri!showDividers,
          alignVertical: ri!alignVertical,
          spacing: a!defaultValue(value: ri!spacing, default: "DENSE"),
          marginAbove: a!defaultValue(value: ri!marginAbove, default: "LESS"),
          marginBelow: a!defaultValue(value: ri!marginBelow, default: "LESS"),
          stackWhen: a!defaultValue(value: ri!stackWhen, default: #"_a-0000e851-089c-8000-9bcb-011c48011c48_358943"),
          columns: 
          a!localVariables(
            local!indexRow: fv!item,
            /*Account for columns, and add empty columns if applicable*/
            #"SYSTEM_SYSRULES_forEach"(
              items: local!enumeratedColumns,
              expression: 
              a!localVariables(
                local!indexColumn: (local!indexRow * local!numColumns) + fv!index,
                if(and(
                    ri!applyPlaceholders = false,
                    local!indexColumn > local!numContents
                  ),
                  {},
                  if(local!indexColumn > local!numContents,
                    if(local!applyPlaceholders,
                      #"SYSTEM_SYSRULES_columnLayout"(
                        width: index(local!enumeratedWidths, fv!index, null)
                      ),
                      null
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: index({ri!contents}, local!indexColumn, {}),
                      width: index(local!enumeratedWidths, fv!index, null)
                    )
                  )
                )
              )
            )
          )
        )
      )
    /*)*/
  )
)
